 const checkChatLayout=async()=>{
   const layout=await page.evaluate(()=>{
     const bubble=document.querySelector('.agent-turn.user'),suggestions=document.querySelector('.agent-suggestions'),modal=document.querySelector('.campaign-agent-form')
     const rgb=value=>(value.match(/[\d.]+/g)||[]).map(Number)
     let background=[255,255,255],nodes=[]
     for(let element=bubble;element;element=element.parentElement)nodes.unshift(element)
     for(const element of nodes){const color=rgb(getComputedStyle(element).backgroundColor),alpha=color[3]??1;background=background.map((v,i)=>alpha*color[i]+(1-alpha)*v)}
     const luminance=color=>color.slice(0,3).map(v=>v/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0)
     const a=luminance(rgb(getComputedStyle(bubble).color)),b=luminance(background)
     const chat=modal.querySelector('.campaign-agent-chat')
     return {contrast:(Math.max(a,b)+.05)/(Math.min(a,b)+.05),width:modal.getBoundingClientRect().width,viewport:innerWidth,chatWidth:chat.getBoundingClientRect().width,chatPosition:getComputedStyle(chat).position,sidebar:document.querySelector('.campaign-agent-form .stepper-sidebar').getBoundingClientRect().width,overflow:suggestions.scrollWidth-suggestions.clientWidth,
       chatBorder:parseFloat(getComputedStyle(document.querySelector('.campaign-agent-chat')).borderLeftWidth)}
   })
   assert(layout.contrast>=4.5,`User message contrast ${layout.contrast}`)
   assert(Math.abs(layout.width-layout.viewport*.9)<=1,`Modal must use 90% of viewport: ${JSON.stringify(layout)}`)
   assert(layout.chatWidth>=300 && layout.chatWidth<=360,'Chat leaves more room for the form')
   assert.equal(layout.chatPosition,layout.viewport>1150?'static':'absolute','Chat stays beside the form on desktop')
   assert.equal(layout.sidebar,260,'Sidebar uses the existing campaign form width')
   assert(layout.overflow<=1,'Suggestions must wrap without horizontal scrolling');assert(layout.chatBorder>=1,'Chat separator must be visible')
 }
